import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Клиент, мод и live","description":"","frontmatter":{"pageId":"developers/client","contentRevision":5},"headers":[],"relativePath":"ru/developers/client.md","filePath":"ru/developers/client.md"}'),r={name:"ru/developers/client.md"};function n(o,e,s,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="клиент-мод-и-live" tabindex="-1">Клиент, мод и live <a class="header-anchor" href="#клиент-мод-и-live" aria-label="Permalink to &quot;Клиент, мод и live&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Client.Core: все сетевые вызовы async/cancellable; состояние UI в SharedState; неподтверждённые мутации в outbox. Никаких Verse/RimWorld references. Мод касается игровых объектов только на главном потоке: результаты фоновой работы через MainThread.Post. Harmony patches — по одному на метод с пояснением причины.</p><p>Пешки/предметы передаются ThingBlobs. При входе в мир с возможными совпадающими id нужны newIds:true и ResetMapIndex перед spawn ранее spawned blob. Ссылки на внешние объекты требуют приведения к миру получателя. Pawn equality по thingIDNumber: нельзя Destroy десериализованную копию, равную живой пешке.</p><p>В live зеркало — не самостоятельная симуляция. Coop права на собственных пешек хозяина отличаются от владения привезёнными гостевыми; cleanup не должен возвращать хозяйских пешек почтой.</p><h2 id="client-intent" tabindex="-1">Путь UI-намерения и граница главного потока <a class="header-anchor" href="#client-intent" aria-label="Permalink to &quot;Путь UI-намерения и граница главного потока {#client-intent}&quot;">​</a></h2><p>UI снимает выбранные данные и создаёт намерение, Core отправляет cancellable запрос и обновляет SharedState. Сетевой callback не должен читать/создавать Verse-объекты; перенос результата в игру выполняется MainThread.Post. Отмена ожидания и отмена уже принятой серверной операции различаются.</p><p>Для отправок сохраняются журнал и точный snapshot перед сетевой мутацией. При replay используй исходное намерение, не пересобирай товар по текущему выделению. Для получения сначала зафиксируй карту с доставкой, потом подтверждай. Unit-тест Core не доказывает правильность Scribe/ThingBlobs и построения новой карты.</p><h2 id="pawn-lifecycle" tabindex="-1">Пешки: id, отношения и возврат <a class="header-anchor" href="#pawn-lifecycle" aria-label="Permalink to &quot;Пешки: id, отношения и возврат {#pawn-lifecycle}&quot;">​</a></h2><p>Десериализованная пешка может равняться живой по thingIDNumber: Destroy копии способен затронуть настоящую. При входе в другой мир обновляй id и map index, согласуй внешние ссылки на faction/ideo/policies. Для ухода/возвращения используй существующие PawnExit/RelationLedger пути, иначе потеряются взаимные отношения и UI-кеш.</p><p>Различай владельца вещи, игрока с правом приказа и writer карты. Coop назначает хозяйских пешек, live-визит переносит гостевых; общий cleanup не должен отправить первых партнёру посылкой. Этот случай требует проверки двумя настоящими клиентами.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>RimWorld 1.7 использует Waylith/CoreCLR, не Unity; UnityEngine — stub. Исследуй реальный тип игры перед предположениями. Локальная сборка и unit tests не заменяют два реальных клиента для игровых изменений.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./../players/coop">Постоянная совместная колония</a></li><li><a href="./protocol">Протокол и идемпотентность</a></li></ul>',16)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
